import { FC } from 'react';

interface TimePickerProps {
    /** 是否打开 */
    open: boolean;
    /** 当前值 (HH:mm 或 HH:mm:ss 格式) */
    value?: string;
    /** 默认值 */
    defaultValue?: string;
    /** 精度 */
    precision?: 'hour' | 'minute' | 'second';
    /** 标题 */
    title?: string;
    /** 分钟步长 */
    minuteStep?: number;
    /** 确认回调 */
    onConfirm?: (value: string) => void;
    /** 取消回调 */
    onCancel?: () => void;
    /** 关闭回调 */
    onClose?: () => void;
}

declare const TimePicker: FC<TimePickerProps>;

export { TimePicker, TimePicker as default };
export type { TimePickerProps };
